import {useRouteQuery} from '@github-ui/react-core/future/use-route-query'
import {copilotCodeGenerationRoute, stafftoolsCopilotCodeGenerationRoute} from './copilot-code-generation-route'
import {Stack} from '@primer/react'
import {clsx} from 'clsx'
import ColumnChart from '@github-ui/copilot-insights-shared/components/charts/ColumnChart'
import {
  indigoBiColorShades,
  greenBiColorShades,
  purpleBiColorShades,
  purpleShades,
} from '@github-ui/copilot-insights-shared/components/charts/utils/chart-colors'
import {Header} from '@github-ui/copilot-insights-shared/components/header/Header'
import DataDisclaimer from '@github-ui/copilot-insights-shared/components/header/DataDisclaimer'
import MetricCards from '@github-ui/copilot-insights-shared/components/metric-cards/MetricCards'
import {useQuerySanitizer} from '@github-ui/copilot-insights-shared/hooks/useQuerySanitizer'
import {CopilotBlankslate} from '@github-ui/copilot-insights-shared/components/CopilotBlankslate'
import styles from '../styles.module.css'
import {useMatch} from '@github-ui/react-router'

export function CopilotCodeGeneration() {
  const stafftoolsMatch = useMatch(stafftoolsCopilotCodeGenerationRoute.path)
  const routeToUse = stafftoolsMatch ? stafftoolsCopilotCodeGenerationRoute : copilotCodeGenerationRoute

  const payload = useRouteQuery(routeToUse, 'mainQuery')
  const {
    codeGenerationMetrics,
    copilotLicenseManagementLink,
    aiControlsLink,
    displayBlankslate,
    displayError,
    displayCodeGenerationDisclaimer,
    exportFilesUrl,
    slug,
    businessId,
    canonicalQueryParams,
    insightsOptedIn,
  } = payload?.data ?? {}

  useQuerySanitizer(canonicalQueryParams)
  const renderCopilotGenerationCharts = () => {
    if (insightsOptedIn === false) {
      return (
        <CopilotBlankslate
          type="policy-disabled"
          dashboardType="code-generation"
          aiControlsLink={aiControlsLink}
          testId="copilot-code-generation-policy-disabled"
        />
      )
    } else if (displayBlankslate || !codeGenerationMetrics) {
      return (
        <CopilotBlankslate
          type="welcome"
          dashboardType="code-generation"
          copilotLicenseManagementLink={copilotLicenseManagementLink}
          testId="copilot-code-generation-blankslate"
        />
      )
    } else if (displayError) {
      return (
        <CopilotBlankslate
          type="error"
          dashboardType="code-generation"
          copilotLicenseManagementLink={copilotLicenseManagementLink}
          testId="copilot-code-generation-error"
        />
      )
    }

    const metricCardsData = codeGenerationMetrics.metricCardsData.data

    return (
      <div className="flex-xl-row flex-column width-xl-auto width-full">
        <Stack direction="horizontal" wrap="wrap" className="gap-3">
          <Stack.Item grow>
            <MetricCards
              cards={[
                {
                  title: 'Lines of code changed with AI',
                  value: metricCardsData.linesChangedByAllModesCardData,
                  description: 'Lines of code added and deleted across all modes during the current calendar month',
                },
                {
                  title: 'Agent Contribution',
                  value: metricCardsData.agentContributionCardData,
                  description:
                    'Percentage of lines of code added and deleted by agents during the current calendar month',
                },
                {
                  title: 'Average lines deleted by agent',
                  value: metricCardsData.averageLinesDeletedByAgentCardData,
                  description:
                    'Average lines of code deleted by agents on behalf of active users during the current calendar month',
                },
              ]}
            />
          </Stack.Item>
          <Stack.Item grow className="width-full">
            <ColumnChart
              payload={codeGenerationMetrics.dailyTotalLinesOfCode}
              title="Daily total of lines added and deleted"
              description="Total lines of code added to and deleted from the codebase across all modes"
              yAxisTitle="Lines of code"
              chartWidth="full"
              columnColours={indigoBiColorShades}
            />
          </Stack.Item>
          <Stack.Item grow className="width-full">
            <div className="d-flex flex-column flex-xl-row gap-3 width-full flex-xl-items-stretch">
              <div className="flex-1 min-width-0 d-flex flex-column">
                <ColumnChart
                  payload={codeGenerationMetrics.userInitiatedCodeChanges}
                  title="User-initiated code changes"
                  description="Compares the total lines of code suggested and manually added by users through code completions and chat panel actions (insert, copy, and apply)"
                  yAxisTitle="Lines of code"
                  chartWidth="full"
                  columnColours={greenBiColorShades}
                />
              </div>
              <div className="flex-1 min-width-0 d-flex flex-column">
                <ColumnChart
                  payload={codeGenerationMetrics.agentInitiatedCodeChanges}
                  title="Agent-initiated code changes"
                  description="Compares the total lines of code automatically added to and deleted from the codebase by agents on behalf of users, combining edit, agent, and custom modes"
                  yAxisTitle="Lines of code"
                  chartWidth="full"
                  columnColours={purpleBiColorShades}
                />
              </div>
            </div>
          </Stack.Item>
          <Stack.Item grow className="width-full">
            <div className="d-flex flex-column flex-xl-row gap-3 width-full flex-xl-items-stretch">
              <div className="flex-1 min-width-0 d-flex flex-column">
                <ColumnChart
                  payload={codeGenerationMetrics.userInitiatedCodeChangesPerModel}
                  title="User-initiated code changes per model"
                  description="Compares the total lines of code suggested and manually added by users, grouped by model used"
                  yAxisTitle="Lines of code"
                  chartWidth="full"
                  columnColours={greenBiColorShades}
                />
              </div>
              <div className="flex-1 min-width-0 d-flex flex-column">
                <ColumnChart
                  payload={codeGenerationMetrics.agentInitiatedCodeChangesPerModel}
                  title="Agent-initiated code changes per model"
                  description="Compares the total lines of code added and deleted by agents on behalf of users, grouped by model used"
                  yAxisTitle="Lines of code"
                  chartWidth="half"
                  columnColours={purpleShades}
                />
              </div>
            </div>
          </Stack.Item>
          <Stack.Item grow className="width-full">
            <div className="d-flex flex-column flex-xl-row gap-3 width-full flex-xl-items-stretch">
              <div className="flex-1 min-width-0 d-flex flex-column">
                <ColumnChart
                  payload={codeGenerationMetrics.userInitiatedCodeChangesPerLanguage}
                  title="User-initiated code changes per language"
                  description="Compares the total lines of code suggested and manually added by users, grouped by language used"
                  yAxisTitle="Lines of code"
                  chartWidth="half"
                  columnColours={greenBiColorShades}
                />
              </div>
              <div className="flex-1 min-width-0 d-flex flex-column">
                <ColumnChart
                  payload={codeGenerationMetrics.agentInitiatedCodeChangesPerLanguage}
                  title="Agent-initiated code changes per language"
                  description="Compares the total lines of code added and deleted by agents on behalf of users, grouped by language used"
                  yAxisTitle="Lines of code"
                  chartWidth="half"
                  columnColours={purpleBiColorShades}
                />
              </div>
            </div>
          </Stack.Item>
        </Stack>
      </div>
    )
  }

  return (
    <div data-testid="copilot-code-generation" className="d-flex flex-column gap-3">
      <hr className={clsx('d-md-none mt-0 mb-0', styles.CopilotInsightsPageDivider)} />
      {displayCodeGenerationDisclaimer && <DataDisclaimer testId="copilot-code-generation-disclaimer" />}
      <Header
        title={'IDE code generation'}
        slug={slug}
        businessId={businessId}
        exportFilesUrl={exportFilesUrl}
        disableControls={displayBlankslate || displayError || insightsOptedIn === false}
        page="code-generation"
      />
      {renderCopilotGenerationCharts()}
    </div>
  )
}

try{ CopilotCodeGeneration.displayName ||= 'CopilotCodeGeneration' } catch {}